-- BETWEEN US v2.3 PARTNER LINK — run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.partner_sessions(id uuid primary key default gen_random_uuid(), status text not null default 'waiting' check(status in ('waiting','connected','closed')), invite_hash text unique not null, expires_at timestamptz not null, created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.partner_members(session_id uuid not null references public.partner_sessions(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('A','B')),joined_at timestamptz not null default now(),primary key(session_id,user_id),unique(session_id,role),unique(user_id,session_id));
create table if not exists public.partner_assessments(session_id uuid not null references public.partner_sessions(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,answers jsonb not null default '{}'::jsonb,categories text[] not null default '{}',extra text not null default '',submitted_at timestamptz,share_consent boolean not null default false,updated_at timestamptz not null default now(),primary key(session_id,user_id));
create table if not exists public.partner_notifications(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.partner_sessions(id) on delete cascade,recipient_id uuid references auth.users(id) on delete cascade,event_type text not null,title text not null,body text not null default '',created_at timestamptz not null default now(),read_at timestamptz);
create table if not exists public.partner_goals(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.partner_sessions(id) on delete cascade,created_by uuid not null references auth.users(id),title text not null,description text not null default '',owner text not null default 'both' check(owner in ('A','B','both')),target_date date,status text not null default 'active' check(status in ('active','paused','completed','replaced')),created_at timestamptz not null default now());
create table if not exists public.partner_action_plans(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.partner_sessions(id) on delete cascade,created_by uuid not null references auth.users(id),person_a text not null default '',person_b text not null default '',shared text not null default '',goal text not null default '',follow_up date,status text not null default 'proposed' check(status in ('proposed','confirmed','paused','replaced','completed')),created_at timestamptz not null default now());
create or replace function public.is_partner(p_session uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from partner_members where session_id=p_session and user_id=auth.uid()) $$;
create or replace function public.leave_partner_session(p_session_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin delete from partner_members where session_id=p_session_id and user_id=auth.uid(); if not found then raise exception 'Not a participant'; end if; update partner_sessions set status='closed' where id=p_session_id; end $$;
alter table public.partner_sessions enable row level security; alter table public.partner_members enable row level security; alter table public.partner_assessments enable row level security; alter table public.partner_notifications enable row level security; alter table public.partner_goals enable row level security; alter table public.partner_action_plans enable row level security;
create policy "members read own sessions" on public.partner_sessions for select to authenticated using(public.is_partner(id));
create policy "members read roster" on public.partner_members for select to authenticated using(public.is_partner(session_id));
create policy "members read own or mutually shared assessment" on public.partner_assessments for select to authenticated using(user_id=auth.uid() or (share_consent and submitted_at is not null and exists(select 1 from partner_assessments mine where mine.session_id=partner_assessments.session_id and mine.user_id=auth.uid() and mine.share_consent and mine.submitted_at is not null) and public.is_partner(session_id)));
create policy "owner inserts or updates own assessment" on public.partner_assessments for insert to authenticated with check(user_id=auth.uid() and public.is_partner(session_id));
create policy "owner updates own assessment" on public.partner_assessments for update to authenticated using(user_id=auth.uid() and public.is_partner(session_id)) with check(user_id=auth.uid() and public.is_partner(session_id));
create policy "recipient reads notifications" on public.partner_notifications for select to authenticated using(public.is_partner(session_id) and (recipient_id is null or recipient_id=auth.uid()));
create policy "participants update notification read state" on public.partner_notifications for update to authenticated using(public.is_partner(session_id) and (recipient_id is null or recipient_id=auth.uid())) with check(public.is_partner(session_id) and (recipient_id is null or recipient_id=auth.uid()));
create policy "participants insert notifications" on public.partner_notifications for insert to authenticated with check(public.is_partner(session_id));
create policy "participants read goals" on public.partner_goals for select to authenticated using(public.is_partner(session_id));
create policy "participants create goals" on public.partner_goals for insert to authenticated with check(created_by=auth.uid() and public.is_partner(session_id));
create policy "participants update goals" on public.partner_goals for update to authenticated using(public.is_partner(session_id)) with check(public.is_partner(session_id));
create policy "participants read plans" on public.partner_action_plans for select to authenticated using(public.is_partner(session_id));
create policy "participants create plans" on public.partner_action_plans for insert to authenticated with check(created_by=auth.uid() and public.is_partner(session_id));
create policy "participants update plans" on public.partner_action_plans for update to authenticated using(public.is_partner(session_id)) with check(public.is_partner(session_id));
grant select on public.partner_sessions,public.partner_members,public.partner_assessments,public.partner_notifications,public.partner_goals,public.partner_action_plans to authenticated;
grant insert,update on public.partner_assessments,public.partner_notifications,public.partner_goals,public.partner_action_plans to authenticated;
grant execute on function public.leave_partner_session(uuid) to authenticated;
-- Realtime publication: add notifications table (ignore duplicate if already included).
do $$ begin alter publication supabase_realtime add table public.partner_notifications; exception when duplicate_object then null; when undefined_object then null; end $$;
create policy "participants delete visible notifications" on public.partner_notifications for delete to authenticated using(public.is_partner(session_id) and (recipient_id is null or recipient_id=auth.uid()));
grant delete on public.partner_notifications to authenticated;
